-- Rückbau 199: ally_ui_funktion_erlaubt wörtlich wie vorher (werkzeuge/m199/vorher/); Beschreibung der Funktion fragen zurück auf den alten Text,
-- nur wenn sie noch den Text von 199 hat. Nur auf dem Stand von 199. Nur als Ganzes in einer Transaktion.
DO $m$
BEGIN
  IF (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_ui_funktion_erlaubt'])) IS NOT DISTINCT FROM 'dd0e8be281eab406ea71d508ad85a204' AND (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (WITH t AS (SELECT c.oid, c.relname::text AS tab FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind::text = ANY (ARRAY['r', 'p']) AND c.relname::text = ANY (ARRAY['ally_personen', 'ally_ui_funktionen', 'matrix_direct_rooms'])) SELECT 'S|' || t.tab || '|' || a.attname::text || '|' || format_type(a.atttypid, a.atttypmod) || '|' || CASE WHEN a.attnotnull THEN 'NN' ELSE '-' END || '|' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || '|' || a.attidentity::text || a.attgenerated::text AS z FROM t JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid = t.oid AND d.adnum = a.attnum UNION ALL SELECT 'C|' || t.tab || '|' || co.conname::text || '|' || co.contype::text || '|' || pg_get_constraintdef(co.oid) FROM t JOIN pg_constraint co ON co.conrelid = t.oid UNION ALL SELECT 'I|' || t.tab || '|' || ic.relname::text || '|' || pg_get_indexdef(i.indexrelid) FROM t JOIN pg_index i ON i.indrelid = t.oid JOIN pg_class ic ON ic.oid = i.indexrelid UNION ALL SELECT 'T|' || t.tab || '|' || tg.tgname::text || '|' || pg_get_triggerdef(tg.oid) || '|' || tg.tgenabled::text FROM t JOIN pg_trigger tg ON tg.tgrelid = t.oid AND NOT tg.tgisinternal) x) IS NOT DISTINCT FROM 'a3f2451f31a14cb1a0c4fdac14938484'
    THEN RAISE EXCEPTION 'Rückbau 199: schon zurückgebaut, nichts geändert'; END IF;
  IF (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_ui_funktion_erlaubt'])) IS DISTINCT FROM '8dbe9d8c9ccca2093be592b14c7de603' OR (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (WITH t AS (SELECT c.oid, c.relname::text AS tab FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind::text = ANY (ARRAY['r', 'p']) AND c.relname::text = ANY (ARRAY['ally_personen', 'ally_ui_funktionen', 'matrix_direct_rooms'])) SELECT 'S|' || t.tab || '|' || a.attname::text || '|' || format_type(a.atttypid, a.atttypmod) || '|' || CASE WHEN a.attnotnull THEN 'NN' ELSE '-' END || '|' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || '|' || a.attidentity::text || a.attgenerated::text AS z FROM t JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid = t.oid AND d.adnum = a.attnum UNION ALL SELECT 'C|' || t.tab || '|' || co.conname::text || '|' || co.contype::text || '|' || pg_get_constraintdef(co.oid) FROM t JOIN pg_constraint co ON co.conrelid = t.oid UNION ALL SELECT 'I|' || t.tab || '|' || ic.relname::text || '|' || pg_get_indexdef(i.indexrelid) FROM t JOIN pg_index i ON i.indrelid = t.oid JOIN pg_class ic ON ic.oid = i.indexrelid UNION ALL SELECT 'T|' || t.tab || '|' || tg.tgname::text || '|' || pg_get_triggerdef(tg.oid) || '|' || tg.tgenabled::text FROM t JOIN pg_trigger tg ON tg.tgrelid = t.oid AND NOT tg.tgisinternal) x) IS DISTINCT FROM 'a3f2451f31a14cb1a0c4fdac14938484' THEN RAISE EXCEPTION 'Rückbau 199: nicht im Stand von 199, nichts geändert'; END IF;
  PERFORM set_config('m199.uif', (SELECT coalesce(md5(string_agg((to_jsonb(x) - CASE WHEN x.schluessel = 'fragen' THEN 'beschreibung' ELSE '-' END)::text, E'\n' ORDER BY x.schluessel COLLATE "C")), '-') FROM public.ally_ui_funktionen x), true);
END $m$;
UPDATE public.ally_ui_funktionen SET beschreibung = 'Fragen stellen und Aufträge geben, auch ohne Chat.' WHERE schluessel = 'fragen' AND beschreibung = 'Fragen stellen und Aufträge geben. Die Antwort kommt in den Chat.';
CREATE OR REPLACE FUNCTION public.ally_ui_funktion_erlaubt(p_person text, p_rolle text, p_schluessel text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Darf die Person diese Seite sehen (Migration 64)? Register an, Schalter (Pakete) nicht aus, Paket gebucht, dann das Recht der Seite (ally_hat_recht), nie der Rollenname.
  -- Migration 161 (Bauplan B4b, F9): nur noch das Recht entscheidet; die Spalte rollen und p_rolle werden nicht mehr ausgewertet (p_rolle bleibt für die Aufrufer).
  -- Seiten ohne eigenes Recht (Startseite, Einstellungen, Benachrichtigungen, KI-Verbrauch) gelten für alle Personen außer Personen mit einer Rolle der Art talent.
  -- Seiten nur für Admins haben das Recht „admin“. Rechte für die eigenen Daten eines Talents (nur_selbst, z. B. „Eigenes Profil“) öffnen eine Seite nur für
  -- Talent-Personen (Rolle der Art talent und talent_id); Admins haben solche Rechte zwar im Katalog, aber kein eigenes Profil.
  -- KI-Verbrauch zusätzlich nur für Admins oder für alle, wenn ki_kopf_sichtbar = 'alle' (S3.4).
  SELECT coalesce((
    SELECT f.an AND coalesce(sch.an, true) AND (f.modul IS NULL OR plattform_modul_an(f.modul))
       AND CASE WHEN f.recht IS NULL THEN NOT EXISTS (SELECT 1 FROM ally_personen p JOIN ally_rollen r ON r.schluessel = p.rolle AND r.art = 'talent'
                                                       WHERE p.matrix_user_id = p_person)
                WHEN coalesce(x.nur_selbst, false) THEN ally_person_ist_talent(p_person) AND ally_hat_recht(p_person, f.recht)
                ELSE ally_hat_recht(p_person, f.recht) END
       AND (f.schluessel <> 'ki-verbrauch' OR coalesce(ally_hat_recht(p_person, 'admin'), false) OR ally_einstellung('ki_kopf_sichtbar') = 'alle')
    FROM ally_ui_funktionen f LEFT JOIN ally_ui_funktion_schalter sch ON sch.schluessel = f.schluessel
    LEFT JOIN ally_rechte x ON x.schluessel = f.recht
    WHERE f.schluessel = p_schluessel), false)
$function$;
DO $m$
BEGIN
  IF (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_ui_funktion_erlaubt'])) IS DISTINCT FROM 'dd0e8be281eab406ea71d508ad85a204' THEN RAISE EXCEPTION 'Rückbau 199: Funktion nicht wie vorher'; END IF;
  IF (SELECT md5(string_agg(z, E'\n' ORDER BY z COLLATE "C")) FROM (WITH t AS (SELECT c.oid, c.relname::text AS tab FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname::text = 'public' COLLATE "C" AND c.relkind::text = ANY (ARRAY['r', 'p']) AND c.relname::text = ANY (ARRAY['ally_personen', 'ally_ui_funktionen', 'matrix_direct_rooms'])) SELECT 'S|' || t.tab || '|' || a.attname::text || '|' || format_type(a.atttypid, a.atttypmod) || '|' || CASE WHEN a.attnotnull THEN 'NN' ELSE '-' END || '|' || coalesce(pg_get_expr(d.adbin, d.adrelid), '') || '|' || a.attidentity::text || a.attgenerated::text AS z FROM t JOIN pg_attribute a ON a.attrelid = t.oid AND a.attnum > 0 AND NOT a.attisdropped LEFT JOIN pg_attrdef d ON d.adrelid = t.oid AND d.adnum = a.attnum UNION ALL SELECT 'C|' || t.tab || '|' || co.conname::text || '|' || co.contype::text || '|' || pg_get_constraintdef(co.oid) FROM t JOIN pg_constraint co ON co.conrelid = t.oid UNION ALL SELECT 'I|' || t.tab || '|' || ic.relname::text || '|' || pg_get_indexdef(i.indexrelid) FROM t JOIN pg_index i ON i.indrelid = t.oid JOIN pg_class ic ON ic.oid = i.indexrelid UNION ALL SELECT 'T|' || t.tab || '|' || tg.tgname::text || '|' || pg_get_triggerdef(tg.oid) || '|' || tg.tgenabled::text FROM t JOIN pg_trigger tg ON tg.tgrelid = t.oid AND NOT tg.tgisinternal) x) IS DISTINCT FROM 'a3f2451f31a14cb1a0c4fdac14938484' THEN RAISE EXCEPTION 'Rückbau 199: Schema nicht wie vorher'; END IF;
  IF current_setting('m199.uif') IS DISTINCT FROM (SELECT coalesce(md5(string_agg((to_jsonb(x) - CASE WHEN x.schluessel = 'fragen' THEN 'beschreibung' ELSE '-' END)::text, E'\n' ORDER BY x.schluessel COLLATE "C")), '-') FROM public.ally_ui_funktionen x) THEN RAISE EXCEPTION 'Rückbau 199: Funktionsliste anders als erwartet geändert'; END IF;
END $m$;
